/// <summary>
///     Constructs a <c>METSupplierChangeCompletedBusinessEventContract</c>.
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <param name = "_vendAccount">Vendor Account</param>
/// <param name = "_coverageWareHouseId">List of warehouse ids</param>
/// <returns>An instance of <c>METSupplierChangeCompletedBusinessEventContract</c>.</returns>
public static METSupplierChangeCompletedBusinessEventContract newFromSupplierChangeCompleted(ItemId _itemId, VendAccount _vendAccount, List _coverageWareHouseId)
{
    METSupplierChangeCompletedBusinessEventContract contract = new METSupplierChangeCompletedBusinessEventContract();
    contract.initialize(_itemId, _vendAccount, _coverageWareHouseId);
    return contract;
}

/// <summary>
/// Item query
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns>Item Id</returns>
[DataMember('Item'), BusinessEventsDataMember("@SYS123828")]
public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;

    return itemId;
}

/// <summary>
/// Item query
/// </summary>
/// <param name = "_vendAccount">Vendor Account</param>
/// <returns>Vendor Account</returns>
[DataMember('VendorAccountNumber'), BusinessEventsDataMember("@SYS12272")]
public VendAccount parmVendAccount(VendAccount _vendAccount = vendAccount)
{
    vendAccount = _vendAccount;

    return vendAccount;
}

/// <summary>
/// List of warehouse ids
/// </summary>
/// <param name = "_coverageWareHouseId">List of warehouse ids</param>
/// <returns>List of sites</returns>
[
 DataMember('CoverageWarehouseId'),
 DataCollection(Types::String),
 BusinessEventsDataMember("@MET:CoverageWarehouseId")]
private List parmCoverageWareHouseId(List _coverageWareHouseId = coverageWareHouseId)
{
    coverageWareHouseId = _coverageWareHouseId;

    return coverageWareHouseId;
}

/// <summary>
/// Initializes the data members
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <param name = "_vendAccount">Vebdor account</param>
/// <param name = "_coverageWareHouseId">Coverage WareHouseId list</param>
private void initialize(ItemId _itemId, VendAccount _vendAccount, List _coverageWareHouseId)
{
    itemId = _itemId;
    vendAccount = _vendAccount;
    coverageWareHouseId = _coverageWareHouseId;
}

/// <summary>
/// creates new object
/// </summary>
private void new()
{
}
